def user_message(error_code, run_id):
    if error_code == 'missing_lesson_id':
        return f'Lesson ID is missing. Add it and try again. Reference: {run_id}'
    return f'We could not complete the import. Try again later. Reference: {run_id}'

assert 'Add it' in user_message('missing_lesson_id', 'run-7')
assert 'traceback' not in user_message('unexpected', 'run-8').lower()
